<?php
declare(strict_types=1);
namespace Modules\Rental;
use PDO;
use App\View;
final class InvoiceDocument
{
    private static function details(array $r,?array $bank):array{$rows=[$r['name']??'—'];foreach(['inn'=>'ИНН ','kpp'=>'КПП '] as $k=>$label)if(!empty($r[$k]))$rows[]=$label.$r[$k];$rows[]=$r['legal_address']??$r['address']??'';if($bank){$rows[]=$bank['bank']??'';foreach(['account'=>'р/с ','bik'=>'БИК ','correspondent_account'=>'к/с '] as $k=>$label)if(!empty($bank[$k]))$rows[]=$label.$bank[$k];}return array_values(array_filter($rows,fn($x)=>$x!==''&&$x!==null));}
    public static function html(PDO $p,array $i):string
    {
        $q=$p->prepare('SELECT c.*,pa.name party_name FROM contracts c JOIN parties pa ON pa.id=c.party_id WHERE c.id=?');$q->execute([$i['contract_id']]);$c=$q->fetch();$q=$p->prepare('SELECT * FROM parties WHERE id=?');$q->execute([$c['party_id']]);$payer=$i['payer_snapshot']?json_decode($i['payer_snapshot'],true):$q->fetch();$payee=$i['payee_snapshot']?json_decode($i['payee_snapshot'],true):$p->query('SELECT * FROM organization WHERE id=1')->fetch();$q=$p->prepare('SELECT * FROM party_bank_accounts WHERE party_id=? AND operational=1 LIMIT 1');$q->execute([$c['party_id']]);$payerBank=$payer['bankDetails']??($q->fetch()?:null);$payeeBank=$payee['bankDetails']??($p->query('SELECT * FROM organization_bank_accounts WHERE is_primary=1 LIMIT 1')->fetch()?:null);$title='Счёт №'.$i['number'].' от '.Documents::dateText($i['issued']);$html='<!doctype html><html lang="ru"><meta charset="UTF-8"><title>'.View::e($title).'</title><style>body{font-family:DejaVu Serif,serif;font-size:11pt}h1{font-size:20pt}h2{font-size:14pt}table{border-collapse:collapse;width:100%}th,td{border:1px solid #333;padding:7px;vertical-align:top}p{margin:6px 0}</style><body><h1>'.View::e($title).'</h1><h2>Получатель</h2>';foreach(self::details($payee,$payeeBank) as $text)$html.='<p>'.View::e($text).'</p>';$html.='<h2>Плательщик</h2>';foreach(self::details($payer,$payerBank) as $text)$html.='<p>'.View::e($text).'</p>';$vat='НДС не указан';if($i['vat']!==null&&$i['amount']!==null){$factor=bcadd('1',bcdiv($i['vat'],'100',12),12);$net=bcdiv($i['amount'],$factor,12);$tax=Billing::round(bcsub($i['amount'],$net,12));$vat='В том числе НДС '.rtrim(rtrim($i['vat'],'0'),'.').'%: '.Controller::money($tax);}$description=$i['purpose']?:($i['title']?:$i['kind']);$html.='<p>Договор №'.View::e($c['number']).($c['document_date']?' от '.Documents::dateText($c['document_date']):'').'</p><table><thead><tr><th>Назначение</th><th>Период</th><th>Сумма с НДС</th></tr></thead><tbody><tr><td>'.View::e($description).'</td><td>'.View::e($i['period']?:'—').'</td><td>'.View::e(Controller::money($i['amount'])).'</td></tr></tbody></table><p>'.View::e($vat).'</p><p>Итого к оплате: '.View::e(Controller::money($i['amount'])).'</p><p>Оплатить до '.Documents::dateText($i['due']).'</p></body></html>';return $html;
    }
}
